   119→function parseCoords(address?: string): [number, number] {
   120→  if (!address) return [36.1911, 44.0092];
   121→  const m = address.match(/(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/);
   122→  return m ? [parseFloat(m[1]), parseFloat(m[2])] : [36.1911, 44.0092];
   123→}
   124→function fmtIQD(n: number) {
   125→  if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B IQD`;
   126→  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M IQD`;
   127→  if (n >= 1e3) return `${(n / 1e3).toFixed(0)}K IQD`;
   128→  return `${n.toFixed(0)} IQD`;
   129→}
