   230→/* ══════════════════════════════════════════════════════════════════════
   231→   LEAFLET MAP (embedded via srcDoc — zero package deps)
   232→══════════════════════════════════════════════════════════════════════ */
   233→function LeafletMap({ lat, lng, label }: { lat: number; lng: number; label?: string }) {
   234→  const safeLabel = (label ?? "Business Location").replace(/['"<>]/g, " ");
   235→  const html = `<!DOCTYPE html><html><head>
   236→  <meta charset="utf-8"/>
   237→  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"/>
   238→  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
   239→  <style>*{margin:0;padding:0}html,body{height:100%;background:#050d1a}#map{height:100%}</style>
   240→  </head><body><div id="map"></div><script>
   241→  const m=L.map('map',{zoomControl:true}).setView([${lat},${lng}],15);
   242→  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OSM',maxZoom:19}).addTo(m);
   243→  const icon=L.divIcon({className:'',
   244→    html:'<div style="width:38px;height:38px;background:#3B82F6;border:3px solid white;border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 0 24px rgba(59,130,246,0.8);font-size:18px">📍</div>',
   245→    iconSize:[38,38],iconAnchor:[19,19]});
   246→  L.marker([${lat},${lng}],{icon}).addTo(m).bindPopup('<b>${safeLabel}</b>').openPopup();
   247→  </script></body></html>`;
   248→  return (
   249→    <iframe srcDoc={html} width="100%" style={{ height: 260, border: 0, borderRadius: "0.875rem", display: "block" }}
   250→      title="GPS" sandbox="allow-scripts" />
   251→  );
   252→}
