   266→  city: "شار", address: "ناونیشان",
   267→};
   268→const SKIP_KEYS = new Set(["password", "confirmPassword", "trustBadge"]);
   269→
   270→function SectorFields({ extraData }: { extraData?: Record<string, any> }) {
   271→  if (!extraData) return <p className="text-xs text-white/20 py-4 text-center">هیچ زانیارییەکی زیادە نییە</p>;
   272→  const entries = Object.entries(extraData).filter(([k, v]) => !SKIP_KEYS.has(k) && v !== null && v !== undefined && v !== "");
   273→  if (!entries.length) return <p className="text-xs text-white/20 py-4 text-center">هیچ زانیارییەکی زیادە نییە</p>;
   274→  return (
   275→    <div className="grid grid-cols-2 gap-2">
   276→      {entries.map(([k, v]) => (
   277→        <div key={k} className="p-3 rounded-xl"
   278→          style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}>
   279→          <p className="text-[9px] font-bold uppercase tracking-widest mb-1" style={{ color: "#3B82F6" }}>
   280→            {FIELD_LABELS[k] ?? k}
   281→          </p>
   282→          <p className="text-xs font-semibold text-white break-all">
   283→            {Array.isArray(v) ? v.join(" · ") : String(v)}
   284→          </p>
   285→        </div>
   286→      ))}
   287→    </div>
   288→  );
   289→}
