   321→function ReviewModal({ reg, onClose, onUpdate }: {
   322→  reg: Registration;
   323→  onClose: () => void;
   324→  onUpdate: (id: number, status: string, reason?: string, badge?: string) => Promise<void>;
   325→}) {
   326→  const [tab, setTab] = useState<"creds" | "docs" | "map">("creds");
   327→  const [action, setAction] = useState("");
   328→  const [badge, setBadge] = useState("verified");
   329→  const [reason, setReason] = useState(reg.rejectionReason ?? "");
   330→  const [saving, setSaving] = useState(false);
   331→  const sm = SM[reg.sectorKey] ?? SM.other;
   332→  const SIcon = sm.icon;
   333→  const [lat, lng] = parseCoords(reg.address);
   334→  const trustBadge = reg.extraData?.trustBadge as string | undefined;
   335→
   336→  const confirm = async () => {
   337→    if (!action) return;
   338→    setSaving(true);
   339→    try {
   340→      await onUpdate(reg.id, action, action === "rejected" ? reason : undefined, action === "approved" ? badge : undefined);
   341→    } finally {
   342→      setSaving(false);
   343→      setAction("");
   344→    }
   345→  };
   346→
   347→  const MODAL_TABS = [
   348→    { key: "creds" as const, label: "بەڵگەنامەی بزنس", icon: User },
   349→    { key: "docs"  as const, label: "بەڵگەنامەکان",    icon: FileText },
   350→    { key: "map"   as const, label: "شوێنی GPS",         icon: MapPin },
   351→  ];
   352→  const ACTIONS = [
   353→    { key: "approved",         icon: CheckCircle2, color: "#10B981", label: "پەسەندکردن و ئیشارەدان" },
   354→    { key: "rejected",         icon: XCircle,      color: "#EF4444", label: "ڕەتکردنەوە لەگەڵ هۆکار" },
   355→    { key: "more_docs_needed", icon: FileText,     color: "#3B82F6", label: "داواکردنی بەڵگەی زیادە" },
   356→    { key: "suspended",        icon: Slash,        color: "#64748B", label: "ڕاگرتنی ئەکاونت" },
   357→  ];
   358→
