/* ── Dev bypass: mint admin token, redirect to verification queue ── */
const handleDevBypass = async () => {
  setDevBypassing(true);
  try {
    const res = await fetch("/api/auth/dev-bypass", { method: "POST" });
    if (!res.ok) throw new Error("endpoint unavailable");
    const { token, user } = await res.json();
    localStorage.setItem("pos_auth_token", token);
    localStorage.setItem("pos_cached_user", JSON.stringify(user));
    window.location.href = "/admin/verification-queue";
  } catch {
    setDevBypassing(false);
  }
};

