import { useEffect, useState } from "react";
import { Switch, Route, Router as WouterRouter, Redirect, useLocation } from "wouter";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { Layout } from "@/components/layout";
import { AuthProvider, useAuth } from "@/contexts/AuthContext";
import { ThemeProvider } from "@/contexts/ThemeContext";
import { motion, AnimatePresence } from "framer-motion";
import { Shield, Eye, EyeOff, Lock } from "lucide-react";
import "@/i18n";
import i18n from "@/i18n";

// Pages
import Dashboard from "@/pages/dashboard";
import Products from "@/pages/products";
import Customers from "@/pages/customers";
import POS from "@/pages/pos";
import Sales from "@/pages/sales";
import Debts from "@/pages/debts";
import Reports from "@/pages/reports";
import NotFound from "@/pages/not-found";
import Register from "@/pages/register";
import UsersPage from "@/pages/users";
import SupplierCatalog from "@/pages/supplier-catalog";
import BuyerDashboard from "@/pages/buyer-dashboard";
import DriverDashboard from "@/pages/driver-dashboard";
import HistoryPage from "@/pages/history";
import MasterAdminPanel from "@/pages/master-admin";
import AdminVerification from "@/pages/admin-verification";

// Terminal B2B pages
import Marketplace from "@/pages/marketplace";
import AIAssistant from "@/pages/ai-assistant";
import Inventory from "@/pages/inventory";
import Logistics from "@/pages/logistics";
import Negotiation from "@/pages/negotiation";
import Financial from "@/pages/financial";
import MarketIntel from "@/pages/market-intel";
import SupplierDirectory from "@/pages/supplier-directory";
import Procurement from "@/pages/procurement";
import NotificationCenter from "@/pages/notifications";
import RewardsCenter from "@/pages/rewards";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: (_failureCount: number, _error: unknown) => {
        if (!navigator.onLine) return false;
        return _failureCount < 1;
      },
      staleTime: 1000 * 60 * 60,
      gcTime: 1000 * 60 * 60 * 24,
      networkMode: "offlineFirst",
    },
    mutations: {
      networkMode: "offlineFirst",
    },
  },
});

/* ── Admin secret (front-end gate) ──────────────────────────────────── */
const ADMIN_GATE_KEY = "linqi_admin_unlocked";
const ADMIN_SECRET   = "linqi-owner-2024";

/* All URL paths that resolve to the admin panel */
const ADMIN_PATHS = ["/admin", "/admin-panel", "/linqi-owner"];

/* ════════════════════════════════════════════════════════════════════
   ADMIN GATE — glassmorphic password screen
════════════════════════════════════════════════════════════════════ */
function AdminGate({ children }: { children: React.ReactNode }) {
  const [unlocked, setUnlocked] = useState(() => sessionStorage.getItem(ADMIN_GATE_KEY) === "1");
  const [pwd, setPwd]           = useState("");
  const [show, setShow]         = useState(false);
  const [err, setErr]           = useState(false);
  const [shaking, setShaking]   = useState(false);

  const attempt = () => {
    if (pwd === ADMIN_SECRET) {
      sessionStorage.setItem(ADMIN_GATE_KEY, "1");
      setUnlocked(true);
    } else {
      setErr(true);
      setShaking(true);
      setTimeout(() => setShaking(false), 500);
      setTimeout(() => setErr(false), 2500);
      setPwd("");
    }
  };

  if (unlocked) return <>{children}</>;

  return (
    <div className="min-h-screen flex items-center justify-center p-4"
      style={{ background: "linear-gradient(135deg,#020c1c 0%,#050d1a 60%,#0a1628 100%)" }}>
      <motion.div
        animate={shaking ? { x: [-10, 10, -8, 8, -4, 4, 0] } : { x: 0 }}
        transition={{ duration: 0.45 }}
        className="w-full max-w-sm rounded-3xl p-8"
        style={{
          background: "rgba(255,255,255,0.06)",
          backdropFilter: "blur(28px)",
          WebkitBackdropFilter: "blur(28px)",
          border: "1px solid rgba(255,255,255,0.12)",
          boxShadow: "0 8px 64px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.10)",
        }}>

        <div className="flex flex-col items-center mb-8">
          <div className="w-16 h-16 rounded-2xl flex items-center justify-center mb-4"
            style={{ background: "rgba(59,130,246,0.15)", border: "1.5px solid rgba(99,179,255,0.35)", boxShadow: "0 0 40px rgba(59,130,246,0.2)" }}>
            <Shield className="w-8 h-8" style={{ color: "#60A5FA" }} />
          </div>
          <h1 className="text-xl font-black text-white mb-1">دەستگەیشتنی تایبەت</h1>
          <p className="text-xs text-center" style={{ color: "#64748B" }}>
            ئەم بەشە تەنها بۆ خاوەنەکانی سیستەم دیاری کراوە
          </p>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold mb-2 uppercase tracking-wider" style={{ color: "#94A3B8" }}>
              <Lock className="inline w-3 h-3 me-1.5" />
              کلیلی نهێنی ئەدمین
            </label>
            <div className="relative">
              <input
                type={show ? "text" : "password"}
                value={pwd}
                onChange={e => { setPwd(e.target.value); setErr(false); }}
                onKeyDown={e => e.key === "Enter" && attempt()}
                placeholder="••••••••••••"
                autoFocus
                className="w-full ps-4 pe-11 py-3 rounded-xl text-sm text-white placeholder-white/20 outline-none transition-all"
                style={{
                  background: "rgba(0,0,0,0.3)",
                  border: err ? "1px solid rgba(239,68,68,0.7)" : "1px solid rgba(255,255,255,0.12)",
                  boxShadow: err ? "0 0 0 3px rgba(239,68,68,0.15)" : undefined,
                }}
              />
              <button type="button" onClick={() => setShow(v => !v)}
                className="absolute end-3 top-1/2 -translate-y-1/2 transition-opacity hover:opacity-80"
                style={{ color: "#64748B" }}>
                {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
            <AnimatePresence>
              {err && (
                <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
                  className="text-[11px] mt-1.5" style={{ color: "#F87171" }}>
                  کلیلی نهێنی هەڵەیە. دووبارە هەوڵبدەرەوە.
                </motion.p>
              )}
            </AnimatePresence>
          </div>

          <button
            type="button"
            onClick={attempt}
            disabled={!pwd}
            className="w-full py-3 rounded-xl font-bold text-sm transition-all"
            style={{
              background: pwd ? "linear-gradient(135deg,#1d4ed8,#3b82f6)" : "rgba(59,130,246,0.2)",
              color: pwd ? "#fff" : "rgba(255,255,255,0.3)",
              border: "1px solid rgba(99,179,255,0.3)",
              boxShadow: pwd ? "0 4px 20px rgba(37,99,235,0.45)" : "none",
            }}>
            داخلبوون
          </button>
        </div>

        <p className="text-center text-[10px] mt-6" style={{ color: "#334155" }}>
          LinQi · پاناڵی بەڕێوەبردن
        </p>
      </motion.div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════════════════
   GLOBAL KEYBOARD SHORTCUT — Ctrl/Cmd + Shift + A → /admin
════════════════════════════════════════════════════════════════════ */
function AdminShortcut() {
  const [, navigate] = useLocation();
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === "a") {
        e.preventDefault();
        navigate("/admin");
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [navigate]);
  return null;
}

/* ════════════════════════════════════════════════════════════════════ */

function DirectionSync() {
  useEffect(() => {
    const apply = (lang: string) => {
      const rtl = lang === "ku" || lang === "ar";
      document.documentElement.dir = rtl ? "rtl" : "ltr";
      document.documentElement.lang = lang;
      localStorage.setItem("linqi_lang", lang);
    };
    apply(i18n.language);
    i18n.on("languageChanged", apply);
    return () => { i18n.off("languageChanged", apply); };
  }, []);
  return null;
}

function Router() {
  const { user, isLoading, isAdmin } = useAuth();
  const [location] = useLocation();

  if (location === "/onboarding") {
    return <Register />;
  }

  /* Owner admin routes — all aliases resolve to the gated panel */
  if (ADMIN_PATHS.includes(location)) {
    return (
      <AdminGate>
        <AdminVerification />
      </AdminGate>
    );
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!user) {
    return <Register />;
  }

  if (user.role === "supplier") {
    return <SupplierCatalog />;
  }

  if (user.role === "buyer") {
    return <BuyerDashboard />;
  }

  if (user.role === "driver") {
    return <DriverDashboard />;
  }

  return (
    <Layout>
      <Switch>
        {/* Core */}
        <Route path="/" component={Dashboard} />

        {/* B2B Terminal */}
        <Route path="/marketplace"        component={Marketplace}        />
        <Route path="/ai-assistant"       component={AIAssistant}        />
        <Route path="/inventory"          component={Inventory}          />
        <Route path="/logistics"          component={Logistics}          />
        <Route path="/negotiation"        component={Negotiation}        />
        <Route path="/financial"          component={Financial}          />
        <Route path="/market-intel"       component={MarketIntel}        />
        <Route path="/supplier-directory" component={SupplierDirectory}  />
        <Route path="/procurement"        component={Procurement}        />
        <Route path="/notifications"      component={NotificationCenter} />
        <Route path="/rewards"            component={RewardsCenter}      />

        {/* POS System */}
        <Route path="/products"  component={Products}    />
        <Route path="/customers" component={Customers}   />
        <Route path="/pos"       component={POS}         />
        <Route path="/sales"     component={Sales}       />
        <Route path="/history"   component={HistoryPage} />
        <Route path="/debts"     component={Debts}       />
        <Route path="/reports"   component={Reports}     />

        {/* Admin — session-authenticated routes */}
        {isAdmin && <Route path="/users"        component={UsersPage}       />}
        {!isAdmin && <Route path="/users"><Redirect to="/" /></Route>}
        {isAdmin && <Route path="/master-admin" component={MasterAdminPanel} />}
        {!isAdmin && <Route path="/master-admin"><Redirect to="/" /></Route>}
        {isAdmin && <Route path="/admin/verification-queue" component={AdminVerification} />}
        {!isAdmin && <Route path="/admin/verification-queue"><Redirect to="/" /></Route>}

        <Route component={NotFound} />
      </Switch>
    </Layout>
  );
}

function App() {
  return (
    <ThemeProvider>
      <QueryClientProvider client={queryClient}>
        <AuthProvider>
          <TooltipProvider>
            <DirectionSync />
            <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}>
              <AdminShortcut />
              <Router />
            </WouterRouter>
            <Toaster />
          </TooltipProvider>
        </AuthProvider>
      </QueryClientProvider>
    </ThemeProvider>
  );
}

export default App;

