  Truck, Share2, UtensilsCrossed, Building2, HeartPulse, ShoppingCart,
  Factory, Layers, Briefcase, ShoppingBag, Pill, CheckCircle2,
} from "lucide-react";
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";
import { motion, AnimatePresence } from "framer-motion";
import SalesPredictor from "@/components/SalesPredictor";
import AIInsightsCard from "@/components/AIInsightsCard";
import { useTranslation } from "react-i18next";
import { useAuth } from "@/contexts/AuthContext";
import { useState } from "react";

const LOW_STOCK_THRESHOLD = 5;

const SECTOR_META: Record<string, { icon: any; color: string; ku: string }> = {
  distributor:  { icon: Share2,          color: "#F59E0B", ku: "دابەشکار" },
  manufacturer: { icon: Factory,         color: "#EF4444", ku: "کارخانە" },
  hospital:     { icon: HeartPulse,      color: "#EC4899", ku: "نەخۆشخانە / کلینیک" },
  supermarket:  { icon: ShoppingBag,     color: "#8B5CF6", ku: "مارکێت" },
  retail_shop:  { icon: ShoppingCart,    color: "#A855F7", ku: "دوکانی تاکەکەسی" },
  restaurant:   { icon: UtensilsCrossed, color: "#F97316", ku: "چێشتخانە" },
  hotel:        { icon: Building2,       color: "#06B6D4", ku: "هۆتێل" },
  pharmacy:     { icon: Pill,            color: "#22C55E", ku: "دەرمانسازی" },
  delivery:     { icon: Truck,           color: "#10B981", ku: "گەیاندن" },
  office:       { icon: Briefcase,       color: "#3B82F6", ku: "نووسینگە" },
  other:        { icon: Layers,          color: "#6B7280", ku: "بزنسی تر" },
};

function SectorWelcomeBanner({ name, sectorKey }: { name: string; sectorKey: string }) {
  const [dismissed, setDismissed] = useState(false);
  const meta = SECTOR_META[sectorKey] ?? SECTOR_META.other;
  const SectorIcon = meta.icon;
  if (dismissed) return null;
  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: -16, scale: 0.97 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, height: 0 }}
        transition={{ type: "spring", stiffness: 260, damping: 22 }}
        className="rounded-2xl p-4 flex items-center gap-4 relative overflow-hidden"
        style={{
          background: `linear-gradient(135deg, ${meta.color}18 0%, ${meta.color}08 100%)`,
          border: `1px solid ${meta.color}35`,
        }}
      >
        <div className="w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0"
          style={{ background: `${meta.color}22`, border: `1.5px solid ${meta.color}45` }}>
          <SectorIcon className="w-6 h-6" style={{ color: meta.color }} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" style={{ color: "#10B981" }} />
            <span className="text-xs font-bold" style={{ color: "#10B981" }}>ئەکاونتت چالاک بوو</span>
          </div>
          <p className="text-sm font-bold text-slate-800 truncate">
            بەخێربێیت، <span style={{ color: meta.color }}>{name}</span>!
          </p>
          <p className="text-xs text-slate-500">بزنسەکەت وەک <strong>{meta.ku}</strong> تۆمارکراوە</p>
        </div>
        <button onClick={() => setDismissed(true)}
          className="flex-shrink-0 w-7 h-7 rounded-lg flex items-center justify-center hover:bg-black/10 transition-colors text-slate-400 text-lg leading-none">
          ×
        </button>
      </motion.div>
    </AnimatePresence>
  );
}

export default function Dashboard() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { data: stats, isLoading, error } = useGetDashboard();
  const { data: products = [] } = useGetProducts();
  const lowStockProducts = products.filter((p) => p.stock < LOW_STOCK_THRESHOLD);

  /* Read sector from the user object (set during registration) or localStorage fallback */
  const sectorKey: string = (user as any)?.sectorKey ?? localStorage.getItem("linqi_sector") ?? "";

